const digitsOnly = (value) => String(value ?? '').replace(/\D/g, '');

const isValidCnpj = (value) => {
  const cnpj = digitsOnly(value);
  if (cnpj.length !== 14 || /^(\d)\1{13}$/.test(cnpj)) return false;
  const calculate = (length) => {
    let sum = 0;
    let weight = length - 7;
    for (let index = 0; index < length; index += 1) {
      sum += Number(cnpj[index]) * weight;
      weight -= 1;
      if (weight === 1) weight = 9;
    }
    const remainder = sum % 11;
    return remainder < 2 ? 0 : 11 - remainder;
  };
  return calculate(12) === Number(cnpj[12]) && calculate(13) === Number(cnpj[13]);
};

const inspectAccessKey = (value) => {
  const key = digitsOnly(value);
  const modelMap = { '55': 'nf-e', '65': 'nfc-e', '57': 'ct-e', '58': 'mdf-e' };
  if (key.length !== 44) return { valid: false, key, model: '', document_type: '', issuer_cnpj: '', reason: 'ACCESS_KEY_LENGTH_INVALID' };
  const model = key.slice(20, 22);
  if (!modelMap[model]) return { valid: false, key, model, document_type: '', issuer_cnpj: key.slice(6, 20), reason: 'ACCESS_KEY_MODEL_UNSUPPORTED' };
  let sum = 0;
  let weight = 2;
  for (let index = 42; index >= 0; index -= 1) {
    sum += Number(key[index]) * weight;
    weight = weight === 9 ? 2 : weight + 1;
  }
  const remainder = sum % 11;
  const expected = remainder === 0 || remainder === 1 ? 0 : 11 - remainder;
  if (expected !== Number(key[43])) return { valid: false, key, model, document_type: modelMap[model], issuer_cnpj: key.slice(6, 20), reason: 'ACCESS_KEY_CHECKSUM_INVALID' };
  return { valid: true, key, model, document_type: modelMap[model], issuer_cnpj: key.slice(6, 20), reason: '' };
};

const normalizeReferenceDate = (value) => {
  const raw = String(value ?? '').trim();
  let year = 0;
  let month = 0;
  let day = 0;
  let normalized = '';
  let match = raw.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (match) {
    year = Number(match[1]); month = Number(match[2]); day = Number(match[3]);
    normalized = match[1] + '-' + match[2] + '-' + match[3];
  } else {
    match = raw.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
    if (!match) return '';
    year = Number(match[3]); month = Number(match[2]); day = Number(match[1]);
    normalized = match[3] + '-' + match[2] + '-' + match[1];
  }
  const date = new Date(Date.UTC(year, month - 1, day));
  if (date.getUTCFullYear() !== year || date.getUTCMonth() !== month - 1 || date.getUTCDate() !== day) return '';
  return normalized;
};

