    /\b\d{5}\.\d{5}\s+\d{5}\.\d{6}\s+\d{5}\.\d{6}\s+\d\s+\d{14}\b/,
  ];
  const markerCount = boletoMarkers.filter((pattern) => pattern.test(compact)).length;
  if (markerCount < 2) return { is_boleto: false, issuer_name: '', issuer_cnpj: '', reference_date: '', due_date: '', document_number: '', recipient_name: '', warnings: [] };
