  s = s.split('\n').join(' ').split('\r').join(' ').split('\t').join(' ').trim();
  while (s.includes('  ')) s = s.split('  ').join(' ');
  return s.slice(0, 120);
};
const digits = (v) => Array.from(String(v ?? '')).filter(ch => ch >= '0' && ch <= '9').join('');
let docType = allowedTypes.has(String(parsed.document_type ?? '').toLowerCase()) ? String(parsed.document_type).toLowerCase() : 'outro';
let department = departmentsByType[docType] ?? String(parsed.department ?? 'revisar').toLowerCase();
if (!['fiscal','contabil','pessoal'].includes(department)) department = 'revisar';
let confidence = Math.max(0, Math.min(Number(parsed.confidence ?? 0) || 0, 1));
let evidence = parsed.evidence && typeof parsed.evidence === 'object' ? parsed.evidence : {};
const reasons = [];
const accessKeyCandidates = [
  ...(Array.isArray(base.extracted_access_keys) ? base.extracted_access_keys : []),
  parsed.access_key
].filter(Boolean);
const extractedText = String(base.prompt ?? '').split('CONTEUDO EXTRAIDO:').slice(1).join('CONTEUDO EXTRAIDO:');
