let modelWarnings = Array.isArray(parsed.warnings) ? parsed.warnings : [];
if (operationalLayout.document_type) {
  docType = operationalLayout.document_type;
  department = operationalLayout.department;
  confidence = Math.max(confidence, 0.95);
  modelWarnings = [...modelWarnings, ...operationalLayout.warnings];
  evidence = {
    ...evidence,
    type: operationalLayout.document_type === 'fgts'
      ? 'FGTS identificado por marcadores explícitos do documento'
      : 'Comprovante de pagamento identificado por marcadores de liquidação',
  };
} else if (boletoLayout.is_boleto) {
  docType = 'boleto';
  department = 'contabil';
  issuerCnpjCandidate = boletoLayout.issuer_cnpj || issuerCnpjCandidate;
  issuerNameCandidate = boletoLayout.issuer_name || issuerNameCandidate;
  documentNumberCandidate = boletoLayout.document_number || documentNumberCandidate;
  recipientNameCandidate = boletoLayout.recipient_name || recipientNameCandidate;
  confidence = Math.max(confidence, 0.95);
  evidence = {
    type: 'Boleto bancario identificado por linha digitavel e ficha de compensacao',
    company: boletoLayout.issuer_name || String(evidence.company ?? ''),
    date: boletoLayout.reference_date || boletoLayout.due_date || String(evidence.date ?? ''),
  };
  modelWarnings = [...modelWarnings, ...boletoLayout.warnings];
  if (invalid) modelWarnings.push('MODEL_OUTPUT_INVALID_JSON_DETERMINISTIC_FALLBACK');
}
if (invalid && !boletoLayout.is_boleto && !operationalLayout.document_type) reasons.push('MODEL_OUTPUT_INVALID_JSON');
if (!String(evidence.type ?? '').trim()) reasons.push('DOCUMENT_TYPE_NOT_EVIDENCED');
if (confidence < 0.80) reasons.push('LOW_CONFIDENCE');
const fiscalIdentity = reconcileFiscalIdentity({
  document_type: docType,
  department,
  issuer_cnpj: issuerCnpjCandidate,
  access_key_candidates: accessKeyCandidates,
