});
department = fiscalIdentity.department;
if (fiscalIdentity.document_type === 'outro') reasons.push('UNKNOWN_OR_UNMAPPED_DOCUMENT_TYPE');
reasons.push(...fiscalIdentity.review_reasons);
const issuerName = clean(issuerNameCandidate, 'EMITENTE NAO IDENTIFICADO');
if (issuerName === 'EMITENTE NAO IDENTIFICADO') reasons.push('ISSUER_NOT_EVIDENCED');
