if (evidenceDate && evidenceDate !== referenceDate) reasons.push('REFERENCE_DATE_EVIDENCE_DIVERGENCE');
const referenceDateSource = boletoLayout.reference_date ? 'issue' : (['issue','transaction','competence','due','unknown'].includes(String(parsed.reference_date_source ?? '').toLowerCase()) ? String(parsed.reference_date_source).toLowerCase() : 'unknown');
